import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 59 · Christmas recipe: Ohio buckeyes (peanut butter balls dipped in chocolate) (Google Trends 3/11: peanut rising topic, christmas candy)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, if you grew up in Ohio, you know exactly what a buckeye is. A little ball of sweet peanut butter, dipped in chocolate, with a round circle of peanut butter left showing on top, so it looks just like the shiny brown nut from the buckeye tree. Every Christmas cookie tray in Ohio has them. If yours doesn't, somebody will ask what's wrong.""",
   "buckeye candy peanut butter chocolate", "EVERY OHIO TRAY")
sc("""But people tell me their buckeyes are too soft and slump into puddles, or the chocolate is thick and streaky, or they fall off the toothpick into the chocolate pot. So tonight I'm giving you my buckeyes, every step, and the five mistakes that make them messy. And stay with me, because the last trick is how to get rid of that toothpick hole on top, and it takes one second.""",
   "messy chocolate candy toothpick", "TOO SOFT")

ch("The Buckeye State")
sc("""Ohio is the Buckeye State, honey. The buckeye tree grows all over Ohio, and its nut is shiny dark brown with a light tan spot on top, like a deer's eye. That's where the name comes from. Buck eye. When I was a girl, we carried a real buckeye nut in our pocket for good luck. My father carried the same one for forty years. It's in my jewelry box now.""",
   "buckeye tree nuts shiny brown", "LIKE A DEER'S EYE")
sc("""The candy came later. The story goes that a woman in Ohio made the first ones in the nineteen sixties, and the recipe spread from church cookbook to church cookbook until every kitchen in the state had it. I first had them at a church Christmas bazaar in nineteen sixty-eight. I bought a dozen, ate them all in the car, and went back in for another dozen.""",
   "church Christmas bazaar 1960s table", "I WENT BACK IN")
sc("""And they're perfect for Christmas, sweetheart, because there's no baking at all. No oven, no cookie sheets, no timing. Just a bowl, your hands, and a pot of chocolate. Children love making them. In a minute I'll tell you the first mistake, and it's the one that makes them too soft to dip.""",
   "children rolling candy balls kitchen", "NO BAKING AT ALL")

ch("What you need")
sc("""Here's what you need, for about five dozen. One and a half cups of creamy peanut butter. Half a cup of butter, softened. One teaspoon of vanilla. A quarter teaspoon of salt. Four cups of powdered sugar. And for dipping, two cups of semi-sweet chocolate chips, or twelve ounces of good chocolate, and a tablespoon of coconut oil or vegetable shortening.""",
   "peanut butter powdered sugar chocolate", "THE INGREDIENTS")
sc("""And here's mistake number one. Natural peanut butter. The kind with the oil on top makes the filling oily and soft, and it never firms up. Use the regular creamy kind from the jar, the kind you don't have to stir. And soft butter, honey, not melted. Melted butter makes the filling greasy, and the balls slump as soon as they warm up.""",
   "creamy peanut butter jar spoon", "REGULAR PEANUT BUTTER")

ch("The filling")
sc("""Step one. Beat the peanut butter, soft butter, vanilla and salt together until smooth. Then add the powdered sugar, a cup at a time, mixing on low so it doesn't fly all over your kitchen. The dough will be stiff, like play dough. Mistake number two is not enough sugar. If it's sticky and soft, the balls won't hold their shape. Add more sugar, a spoon at a time.""",
   "mixing peanut butter dough stiff", "LIKE PLAY DOUGH")
sc("""Here's the test. Roll a little piece between your palms. If it rolls smooth and doesn't stick to your hands, it's right. If it sticks, add more powdered sugar. Every peanut butter is a little different. Some days I need four and a half cups. And don't be afraid to get in there with your hands, honey. It mixes better that way anyway.""",
   "rolling smooth ball palms", "IT SHOULDN'T STICK")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. Now roll the dough into balls about one inch across, about the size of a real buckeye nut. Set them on a baking sheet lined with wax paper or parchment. Make them all the same size, so they look nice on the tray.""",
   "peanut butter balls on wax paper", "THE SIZE OF A BUCKEYE")

ch("Chill them")
sc("""Step two, and this is the one people skip. Mistake number three. Dipping warm, soft balls. They fall off the toothpick, melt in the warm chocolate, and make a mess. Put the whole tray in the freezer for at least thirty minutes, or the icebox for an hour, until the balls are firm and cold. Cold balls hold onto the toothpick and set the chocolate fast.""",
   "tray of candy balls freezer", "FREEZE THEM FIRST")
sc("""And here's a trick from Mrs. Hartman at church, who made five hundred buckeyes every December for the bazaar. Stick the toothpick in each ball before they go in the freezer. Then they freeze solid around the toothpick, and they never slip off. Mrs. Hartman said that one trick saved her about two hundred buckeyes a year.""",
   "toothpicks in candy balls tray", "TOOTHPICK FIRST")

ch("The chocolate")
sc("""Step three, the chocolate. Melt the chocolate chips with the coconut oil or shortening in a small, deep bowl in the microwave, thirty seconds at a time, stirring each time, until it's smooth. Or in a bowl over a pot of barely simmering water. Mistake number four is overheating it. Chocolate burns easily, and burnt chocolate turns thick, dull and grainy. Low and slow, and stir.""",
   "melting chocolate bowl stirring", "LOW AND SLOW")
sc("""The coconut oil or shortening is the secret to a smooth, shiny coat, honey. It thins the chocolate just a little, so it coats evenly and thin, not in a thick, lumpy blanket. And use a small, deep bowl, so the chocolate is deep enough to dip into. A wide, shallow bowl is how buckeyes end up with bald spots.""",
   "small deep bowl melted chocolate", "A SMALL, DEEP BOWL")

sc("""And a word about the chocolate, honey. Chocolate chips work fine, and they're what most Ohio grandmothers use. But a good chocolate bar, chopped, melts smoother and tastes richer. Don't let even one drop of water get into the chocolate while it melts. A single drop makes it seize up, thick and lumpy like mud. Dry bowl, dry spoon, and keep the steam away from it.""",
   "chopped chocolate bar dry bowl", "NOT ONE DROP OF WATER")

ch("Dipping")
sc("""So far, regular peanut butter, enough sugar, same-size balls, frozen with the toothpick in, and chocolate melted low and slow. Now, take out a few balls at a time, and leave the rest in the freezer. Hold the toothpick, and dip each ball into the chocolate, about three quarters of the way up, leaving a round circle of peanut butter showing on top. That's the buckeye's eye.""",
   "dipping buckeye in chocolate", "THE BUCKEYE'S EYE")
sc("""Let the extra chocolate drip off for a few seconds, and give it a little twirl. Then set it back on the wax paper. Mistake number five is dipping them all the way. Then it's just a chocolate peanut butter ball, sweetheart. It's delicious, but it's not a buckeye. In Ohio, that's practically against the law.""",
   "buckeyes drying on wax paper", "PRACTICALLY AGAINST THE LAW")
sc("""And now the trick I promised, for the toothpick hole. After you set the buckeye down and pull out the toothpick, there's a little hole on top. Just touch it with your fingertip and gently smooth the peanut butter over it. One second, and it's gone. It looks like a real buckeye nut, perfectly smooth. Mrs. Hartman's always looked like they came from a candy shop.""",
   "smoothing toothpick hole finger", "ONE SECOND")
sc("""Put the finished tray back in the icebox for about fifteen minutes, until the chocolate is completely set. And if the chocolate in your bowl gets thick while you work, put it back in the microwave for ten seconds. If it gets too low, tip the bowl a little to one side, so it's deeper. Patience, honey. Five dozen buckeyes takes about an hour.""",
   "tray of finished buckeyes", "PATIENCE")

ch("Keeping and giving")
sc("""Buckeyes keep two weeks in the icebox in a tin with wax paper between the layers, and three months in the freezer. Take them out about fifteen minutes before serving, so the peanut butter is soft. They make the best gift in Ohio. Put a dozen in little paper candy cups in a box, and tie it with a red and gray ribbon, if you're an Ohio State fan.""",
   "buckeyes gift box paper cups", "RED AND GRAY")
sc("""And you can make them fancy, sweetheart. Add half a cup of crushed graham crackers or crispy rice cereal to the filling, for a little crunch. Or use dark chocolate. Or sprinkle a few flakes of sea salt on the chocolate before it sets. My granddaughter makes a chocolate chip cookie dough version. In my day, that would've been a scandal.""",
   "buckeyes sea salt dark chocolate", "IT WOULD'VE BEEN A SCANDAL")
sc("""And here's a shortcut for busy people. Press the whole peanut butter mixture into a buttered nine by nine pan, pour the melted chocolate over the top, chill it, and cut it into squares. They call them buckeye bars. They taste exactly the same, and they take fifteen minutes. Mrs. Hartman called them lazy buckeyes. But she ate three.""",
   "buckeye bars pan squares", "LAZY BUCKEYES")

ch("Grandma's kitchen")
sc("""So one more time. Regular creamy peanut butter and soft butter. Enough powdered sugar that the dough doesn't stick. Roll them the size of a buckeye. Toothpick in, and freeze them thirty minutes. Chocolate melted low and slow with a little coconut oil, in a small, deep bowl. Dip them three quarters of the way, and smooth the hole on top. That's a real Ohio buckeye.""",
   "buckeyes Christmas tray Ohio", "A REAL OHIO BUCKEYE")
sc("""Tell me in the comments, sweetheart. Where are you from, and what's the Christmas candy everybody makes there? I'd love to know. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas candy tray evening", "WHERE ARE YOU FROM?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma59", "Ohio Buckeyes EVERYONE's Grandma Made (Why Yours Are Too SOFT)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "The Ohio buckeye (Aesculus glabra), state tree of Ohio, and the buckeye candy popular in Ohio since the 1960s.",
      "Recipe as written by Grandma Ruth: 1 1/2 cups creamy peanut butter, 1/2 cup soft butter, 1 tsp vanilla, 1/4 tsp salt, about 4 cups powdered sugar; frozen 30 minutes; dipped in 2 cups chocolate chips melted with 1 tbsp coconut oil or shortening."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
